<script setup>
import { onMounted,reactive,ref } from 'vue';import http from '../api/http';import { dateText } from '../utils/format'
const data=ref({availablePoints:0,frozenPoints:0,creditScore:0,pointTransactions:{records:[]},creditRecords:{records:[]}}),tab=ref('points'),query=reactive({page:1,size:20});async function load(){data.value=await http.get('/api/wallet',{params:query})}onMounted(load)
</script>
<template><div><div class="page-head"><div><h1>积分与信用</h1><p>每一笔变动都有迹可循，可靠履约让信用持续积累</p></div></div><div class="stat-grid" style="margin-bottom:20px"><div class="stat surface"><strong>{{data.availablePoints}}</strong><span>可用积分</span></div><div class="stat surface"><strong>{{data.frozenPoints}}</strong><span>冻结积分</span></div><div class="stat surface"><strong>{{data.creditScore}}</strong><span>信用分</span></div></div><section class="surface panel"><el-tabs v-model="tab"><el-tab-pane label="积分流水" name="points"><div v-for="tx in data.pointTransactions.records" :key="tx.id" class="list-card" style="background:#f5f7f3;display:flex;justify-content:space-between;gap:12px"><div><strong>{{tx.remark||tx.businessType}}</strong><div class="muted" style="margin-top:6px">{{dateText(tx.createdAt)}} · 余额 {{tx.beforeBalance}} → {{tx.afterBalance}}</div></div><strong :style="{color:tx.changeAmount>=0?'#2f7d68':'#bf4c4c'}">{{tx.changeAmount>0?'+':''}}{{tx.changeAmount}}</strong></div><div v-if="!data.pointTransactions.records?.length" class="empty">暂无积分流水</div></el-tab-pane><el-tab-pane label="信用记录" name="credit"><div v-for="r in data.creditRecords.records" :key="r.id" class="list-card" style="background:#f5f7f3;display:flex;justify-content:space-between;gap:12px"><div><strong>{{r.reason}}</strong><div class="muted" style="margin-top:6px">{{dateText(r.createdAt)}} · {{r.beforeScore}} → {{r.afterScore}}</div></div><strong :style="{color:r.changeValue>=0?'#2f7d68':'#bf4c4c'}">{{r.changeValue>0?'+':''}}{{r.changeValue}}</strong></div><div v-if="!data.creditRecords.records?.length" class="empty">暂无信用变动</div></el-tab-pane></el-tabs><div style="display:flex;justify-content:center"><el-pagination v-if="Math.max(data.pointTransactions.total||0,data.creditRecords.total||0)>query.size" v-model:current-page="query.page" :total="Math.max(data.pointTransactions.total||0,data.creditRecords.total||0)" :page-size="query.size" layout="prev,pager,next" @current-change="load"/></div></section></div></template>
